public class Abraham {
	
	public void run() throws Exception{
		Scanner file = new Scanner(new File("abraham.dat"));
		int times = file.nextInt();
		file.nextLine();
		int abe = 0, other = 0;
		while(times-- > 0) {
			String s = file.nextLine().trim();
			if(s.equals("Abraham"))
				abe++;
			else
				other++;
		}
		System.out.println(abe);
		if(abe > other)
			System.out.println("Honest Abe");
		else
			System.out.println("Better find a hobby");
	}
	
	public static void main(String[]args)throws Exception{
		new Abraham().run();
	}
}

import java.io.*;
import java.util.*;

public class Manning {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(new File("manning.dat"));

        int K = sc.nextInt();

        for (int t = 0; t < K; t++) {
            int n = sc.nextInt();
            int m = sc.nextInt();

            // Map currency names to indices
            Map<String, Integer> currencyIndex = new HashMap<>();
            for (int i = 0; i < n; i++) {
                String name = sc.next();
                currencyIndex.put(name, i);
            }

            // Store edges: from, to, -log(rate)
            // We use -log so that maximizing product becomes minimizing sum
            // Arbitrage exists if there's a negative cycle
            int[] edgeFrom = new int[m];
            int[] edgeTo = new int[m];
            double[] edgeWeight = new double[m];

            for (int i = 0; i < m; i++) {
                String from = sc.next();
                String to = sc.next();
                double rate = sc.nextDouble();

                edgeFrom[i] = currencyIndex.get(from);
                edgeTo[i] = currencyIndex.get(to);
                edgeWeight[i] = -Math.log(rate);
            }

            // Bellman-Ford to detect negative cycle
            double[] dist = new double[n];
            Arrays.fill(dist, 0); // Start all at 0 (virtual source concept)

            // Relax edges n-1 times
            for (int i = 0; i < n - 1; i++) {
                for (int j = 0; j < m; j++) {
                    if (dist[edgeFrom[j]] + edgeWeight[j] < dist[edgeTo[j]]) {
                        dist[edgeTo[j]] = dist[edgeFrom[j]] + edgeWeight[j];
                    }
                }
            }

            // Check for negative cycle (one more relaxation)
            boolean hasArbitrage = false;
            for (int j = 0; j < m; j++) {
                if (dist[edgeFrom[j]] + edgeWeight[j] < dist[edgeTo[j]] - 1e-9) {
                    hasArbitrage = true;
                    break;
                }
            }

            System.out.println(hasArbitrage ? "Cha Ching!!" : "gg");
        }
        sc.close();
    }
}

import java.io.File;
import java.io.FileNotFoundException;
import java.io.FileWriter;
import java.io.IOException;
import java.util.Scanner;

public class Rey {

    public static void main(String[] args) {

        File file = new File("rey.dat");

        try {
            Scanner scan = new Scanner(file);

            while (scan.hasNext()) {
                String teacher = scan.next();

                if (!scan.hasNextInt()) break;
                int count = scan.nextInt();

                System.out.println("INVOICE FOR: " + teacher);
                System.out.println("---------------------------");

                double totalDue = 0.0;

                for (int i = 0; i < count; i++) {
                    String type = scan.next(); // "Hoodie" or "TShirt"
                    String size = scan.next(); // "S", "M", "XL", etc.

                    double price = 0.0;

                    // 1. Determine Base Price
                    if (type.equalsIgnoreCase("Hoodie")) {
                        price = 30.00;
                    } else if (type.equalsIgnoreCase("TShirt")) {
                        price = 15.00;
                    }

                    // 2. Determine Surcharge
                    if (size.equals("XL") || size.equals("XXL")) {
                        price += 2.50;
                    }

                    totalDue += price;

                    // Format: "Hoodie (XL)"
                    String itemDesc = type + " (" + size + ")";

                    // Print line item
                    System.out.printf("%-16s $ %6.2f%n", itemDesc, price);
                }

                System.out.println("---------------------------");
                System.out.printf("%-16s $ %6.2f%n", "Total Due:", totalDue);
                System.out.println();
            }
            scan.close();

        } catch (FileNotFoundException e) {
            System.out.println("File not found.");
        }
    }

}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.FileReader;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.HashMap;
import java.util.TreeSet;

public class Jun {
    public static void main(String[] args) throws IOException {
        new Jun().run();
    }

    private void run() throws IOException {
        BufferedReader file = new BufferedReader(new FileReader("jun.dat"));
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        solve(file, out);

        file.close();
        out.close();
    }

    private static final String MONTHS[] = {
            "Jan", "Feb", "Mar", "Apr", "May", "Jun",
            "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
    };

    private class CityReport {
        private String name;
        private double totalTemp, totalPrecip, coldestTemp;
        private int numEntries, windiest, windiestMonth, windiestDay, coldestTempMonth, coldestTempDay;

        public CityReport(String name) {
            this.name = name;
            totalTemp = totalPrecip = windiest = windiestDay = windiestMonth = numEntries = 0;
            coldestTemp = Double.MAX_VALUE;
        }

        public void addEntry(int month, int day, double temp, double precip, int wind) {
            totalTemp += temp;
            totalPrecip += precip;
            if (wind > windiest) {
                windiest = wind;
                windiestMonth = month;
                windiestDay = day;
            }
            if (temp < coldestTemp) {
                coldestTemp = temp;
                coldestTempMonth = month;
                coldestTempDay = day;
            }
            numEntries++;
        }

        public double getColdestTemp() {
            return coldestTemp;
        }

        public String printColdestTemp() {
            return String.format("%s on %s %d: %.1f F", name, MONTHS[coldestTempMonth - 1], coldestTempDay,
                    coldestTemp);
        }

        @Override
        public String toString() {
            return String.format("%s\n Average Temp: %.1f F\n Total Precip: %.2f in\n Windiest Day: %s %d (%d mph)\n",
                    name, totalTemp / numEntries, totalPrecip, MONTHS[windiestMonth - 1], windiestDay, windiest);
        }
    }

    public void solve(BufferedReader file, PrintWriter out) throws IOException {
        HashMap<String, CityReport> reports = new HashMap<String, CityReport>();
        String line = file.readLine();

        while (line != null) {
            String[] parts = line.split(",");

            if (!reports.containsKey(parts[1])) {
                reports.put(parts[1], new CityReport(parts[1]));
            }
            CityReport report = reports.get(parts[1]);

            int[] date = Arrays.asList(parts[0].split("-")).stream().mapToInt(Integer::parseInt).toArray();
            report.addEntry(date[1], date[2], Double.parseDouble(parts[2]), Double.parseDouble(parts[3]),
                    Integer.parseInt(parts[4]));

            line = file.readLine();
        }

        out.println("City Summaries\n");

        TreeSet<String> sortedNames = new TreeSet<String>(reports.keySet());
        double coldestTemp = Double.MAX_VALUE;
        String coldestCity = "";
        for (String name : sortedNames) {
            out.println(reports.get(name).toString());
            if (reports.get(name).getColdestTemp() < coldestTemp) {
                coldestTemp = reports.get(name).getColdestTemp();
                coldestCity = name;
            }
        }

        out.printf("Coldest Reading Overall\n %s\n", reports.get(coldestCity).printColdestTemp());
    }
}

