public class Jonnie {
	
	int val(String s) {
		int num = 0;
		for(char c:s.toCharArray())
			switch(c) {
			case 'A':num += 1;break;
			case 'B':num += 3;break;
			case 'C':num += 3;break;
			case 'D':num += 2;break;
			case 'E':num += 1;break;
			case 'F':num += 4;break;
			case 'G':num += 2;break;
			case 'H':num += 4;break;
			case 'I':num += 1;break;
			case 'J':num += 8;break;
			case 'K':num += 5;break;
			case 'L':num += 1;break;
			case 'M':num += 3;break;
			case 'N':num += 1;break;
			case 'O':num += 1;break;
			case 'P':num += 3;break;
			case 'Q':num += 10;break;
			case 'R':num += 1;break;
			case 'S':num += 1;break;
			case 'T':num += 1;break;
			case 'U':num += 1;break;
			case 'V':num += 4;break;
			case 'W':num += 4;break;
			case 'X':num += 8;break;
			case 'Y':num += 4;break;
			case 'Z':num += 10;break;
			}
		return num;
	}
	
	public void run() throws Exception{
		Scanner file = new Scanner(new File("jonnie.dat"));
		int times = file.nextInt(), players = file.nextInt(), words = file.nextInt(), curr = 0;
		file.nextLine();
		TreeMap<String, Integer> tm = new TreeMap<String, Integer>();
		TreeSet<Character> played = new TreeSet<Character>();
		int[] scores = new int[players];
		while(words-- > 0) {
			String s = file.next();
			tm.put(s, val(s));
		}
		file.nextLine();
		char[] lets = file.nextLine().trim().toCharArray();
		int max = 0;
		String m = null;
		for(String s:tm.keySet()) 
			if(poss(arrToList(s.toCharArray()), arrToList(lets), played) && tm.get(s) > max) {
				max = tm.get(s);
				m = s;
			}
		for(char c:m.toCharArray())
			played.add(c);
		System.out.println(m+" "+max);
		scores[curr++] = max;
		curr %= players;
		while(times-- > 1) {
			lets = file.nextLine().trim().toCharArray();
			max = 0;
			m = null;
			//System.out.println(let+" "+played);
			for(String s:tm.keySet()) 
				if(poss(arrToList(s.toCharArray()), arrToList(lets), played) && tm.get(s) > max) {
					//System.out.println(let+" "+played);
					max = tm.get(s);
					m = s;
				}
			if(m!=null) {
				for(char c:m.toCharArray())
					played.add(c);
				System.out.println(m+" "+max);
			}
			else
				System.out.println("NO POSSIBLE WORDS");
			scores[curr++] += max;
			curr %= players;
		}
		//System.out.println(Arrays.toString(scores));
		int win = 0;
		for(int i = 0; i < players; i++)
			if(scores[win] < scores[i]) 
				win = i;
		System.out.println("Player "+(win + 1)+" won with a score of "+scores[win]);
	}
	
	public ArrayList<Character> arrToList(char[] ch){
		ArrayList<Character> c = new ArrayList<Character>();
		for(char k:ch)
			c.add(k);
		return c;
	}
	
	public boolean poss(ArrayList<Character> s, ArrayList<Character> ch, TreeSet<Character> p) {
			for(int i = 0; i < s.size(); i++) {
				char c = s.get(i);
				if(ch.contains(c)) {
					ch.remove((Character)c);
					s.remove(i);
					i--;
				}
			}
			//System.out.println(s+" "+ch);
			if(s.size() > 1)return false;
			else if(s.size() == 0)return true;
			else {
				//System.out.println("skdjsdj");
				return p.contains(s.get(0));
			}
	}
	
	public static void main(String[]args)throws Exception{
		new Jonnie().run();
	}
}

import java.io.*;
import java.util.*;

public class Brady {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(new File("brady.dat"));

        int K = sc.nextInt();

        for (int t = 0; t < K; t++) {
            int N = sc.nextInt();
            int Q = sc.nextInt();
            sc.nextLine(); // consume newline

            String[] words = sc.nextLine().split(" ");

            // Build the N-gram model
            // Map from context (N-1 words joined by space) to (word -> count)
            Map<String, Map<String, Integer>> model = new HashMap<>();

            for (int i = 0; i <= words.length - N; i++) {
                // Build context from words[i] to words[i+N-2]
                StringBuilder contextBuilder = new StringBuilder();
                for (int j = i; j < i + N - 1; j++) {
                    if (j > i) contextBuilder.append(" ");
                    contextBuilder.append(words[j]);
                }
                String context = contextBuilder.toString();
                String nextWord = words[i + N - 1];

                // Update counts
                if (!model.containsKey(context)) {
                    model.put(context, new HashMap<>());
                }
                Map<String, Integer> counts = model.get(context);
                counts.put(nextWord, counts.getOrDefault(nextWord, 0) + 1);
            }

            // Answer queries
            for (int q = 0; q < Q; q++) {
                String query = sc.nextLine();

                if (!model.containsKey(query)) {
                    System.out.println("unknown");
                } else {
                    Map<String, Integer> counts = model.get(query);

                    // Find the word with highest count (alphabetically first if tied)
                    String bestWord = null;
                    int bestCount = 0;

                    for (Map.Entry<String, Integer> entry : counts.entrySet()) {
                        String word = entry.getKey();
                        int count = entry.getValue();

                        if (count > bestCount || (count == bestCount && word.compareTo(bestWord) < 0)) {
                            bestWord = word;
                            bestCount = count;
                        }
                    }

                    System.out.println(bestWord);
                }
            }
        }
        sc.close();
    }
}

import java.io.*;
import java.util.*;

public class Vick {

    static class Order {
        int id;
        boolean isBuy;
        int price;
        int quantity;      // remaining quantity
        int visibleQty;    // for iceberg: current visible portion
        int totalQty;      // for iceberg: original total (used for refill tracking)
        int hiddenQty;     // for iceberg: hidden quantity remaining
        int maxVisible;    // for iceberg: max visible size
        boolean isIceberg;
        long timestamp;    // for time priority

        Order(int id, boolean isBuy, int price, int quantity, long timestamp) {
            this.id = id;
            this.isBuy = isBuy;
            this.price = price;
            this.quantity = quantity;
            this.visibleQty = quantity;
            this.totalQty = quantity;
            this.hiddenQty = 0;
            this.maxVisible = quantity;
            this.isIceberg = false;
            this.timestamp = timestamp;
        }

        Order(int id, boolean isBuy, int price, int quantity, int visible, long timestamp) {
            this.id = id;
            this.isBuy = isBuy;
            this.price = price;
            this.quantity = quantity;
            this.totalQty = quantity;
            this.visibleQty = Math.min(visible, quantity);
            this.hiddenQty = quantity - this.visibleQty;
            this.maxVisible = visible;
            this.isIceberg = true;
            this.timestamp = timestamp;
        }

        int getVisibleQuantity() {
            if (isIceberg) {
                return visibleQty;
            }
            return quantity;
        }

        // Fill some quantity from visible portion
        void fill(int amount) {
            int filled = Math.min(amount, getVisibleQuantity());
            quantity -= filled;
            if (isIceberg) {
                visibleQty -= filled;
            }
        }

        // For iceberg: refill visible portion from remaining quantity
        void refillVisible(long newTimestamp) {
            if (!isIceberg || visibleQty > 0 || quantity <= 0) {
                return;
            }
            // Refill visible from remaining quantity
            int refillAmount = Math.min(maxVisible, quantity);
            visibleQty = refillAmount;
            timestamp = newTimestamp;  // goes to back of queue
        }

        boolean isEmpty() {
            return quantity <= 0;
        }
    }

    static long globalTimestamp = 0;
    static List<String> trades;

    // Order books: price -> list of orders (in time priority)
    static TreeMap<Integer, LinkedList<Order>> bids;  // descending by price
    static TreeMap<Integer, LinkedList<Order>> asks;  // ascending by price
    static Map<Integer, Order> orderById;

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(new File("vick.dat"));

        int K = sc.nextInt();

        for (int t = 0; t < K; t++) {
            int N = sc.nextInt();

            // Initialize
            globalTimestamp = 0;
            trades = new ArrayList<>();
            bids = new TreeMap<>(Collections.reverseOrder());  // highest first
            asks = new TreeMap<>();  // lowest first
            orderById = new HashMap<>();

            for (int i = 0; i < N; i++) {
                String op = sc.next();

                if (op.equals("LIMIT")) {
                    int id = sc.nextInt();
                    String side = sc.next();
                    int price = sc.nextInt();
                    int qty = sc.nextInt();
                    boolean isBuy = side.equals("BUY");

                    Order order = new Order(id, isBuy, price, qty, globalTimestamp++);
                    processOrder(order);

                } else if (op.equals("CANCEL")) {
                    int id = sc.nextInt();
                    cancelOrder(id);

                } else if (op.equals("ICEBERG")) {
                    int id = sc.nextInt();
                    String side = sc.next();
                    int price = sc.nextInt();
                    int qty = sc.nextInt();
                    int visible = sc.nextInt();
                    boolean isBuy = side.equals("BUY");

                    Order order = new Order(id, isBuy, price, qty, visible, globalTimestamp++);
                    processOrder(order);
                }
            }

            // Output trades
            for (String trade : trades) {
                System.out.println(trade);
            }
            System.out.println();
        }

        sc.close();
    }

    static void processOrder(Order incoming) {
        if (incoming.isBuy) {
            // Match against asks
            while (!incoming.isEmpty() && !asks.isEmpty()) {
                int bestAskPrice = asks.firstKey();
                if (bestAskPrice > incoming.price) break;

                LinkedList<Order> ordersAtPrice = asks.get(bestAskPrice);

                while (!incoming.isEmpty() && !ordersAtPrice.isEmpty()) {
                    Order resting = ordersAtPrice.peekFirst();

                    int fillQty = Math.min(incoming.getVisibleQuantity(), resting.getVisibleQuantity());
                    if (fillQty > 0) {
                        incoming.fill(fillQty);
                        resting.fill(fillQty);

                        trades.add("TRADE " + incoming.id + " " + resting.id + " " + resting.price + " " + fillQty);
                    }

                    // Refill incoming iceberg if needed (doesn't change queue position since it's not resting)
                    if (incoming.isIceberg && incoming.visibleQty == 0 && !incoming.isEmpty()) {
                        incoming.visibleQty = Math.min(incoming.maxVisible, incoming.quantity);
                    }

                    // Check if resting iceberg needs refill
                    if (resting.isIceberg && resting.visibleQty == 0 && !resting.isEmpty()) {
                        // Remove from front, refill, add to back
                        ordersAtPrice.pollFirst();
                        resting.refillVisible(globalTimestamp++);
                        ordersAtPrice.addLast(resting);
                    } else if (resting.isEmpty()) {
                        ordersAtPrice.pollFirst();
                        orderById.remove(resting.id);
                    }
                }

                if (ordersAtPrice.isEmpty()) {
                    asks.remove(bestAskPrice);
                }
            }
        } else {
            // Match against bids
            while (!incoming.isEmpty() && !bids.isEmpty()) {
                int bestBidPrice = bids.firstKey();
                if (bestBidPrice < incoming.price) break;

                LinkedList<Order> ordersAtPrice = bids.get(bestBidPrice);

                while (!incoming.isEmpty() && !ordersAtPrice.isEmpty()) {
                    Order resting = ordersAtPrice.peekFirst();

                    int fillQty = Math.min(incoming.getVisibleQuantity(), resting.getVisibleQuantity());
                    if (fillQty > 0) {
                        incoming.fill(fillQty);
                        resting.fill(fillQty);

                        trades.add("TRADE " + resting.id + " " + incoming.id + " " + resting.price + " " + fillQty);
                    }

                    // Refill incoming iceberg if needed (doesn't change queue position since it's not resting)
                    if (incoming.isIceberg && incoming.visibleQty == 0 && !incoming.isEmpty()) {
                        incoming.visibleQty = Math.min(incoming.maxVisible, incoming.quantity);
                    }

                    // Check if resting iceberg needs refill
                    if (resting.isIceberg && resting.visibleQty == 0 && !resting.isEmpty()) {
                        ordersAtPrice.pollFirst();
                        resting.refillVisible(globalTimestamp++);
                        ordersAtPrice.addLast(resting);
                    } else if (resting.isEmpty()) {
                        ordersAtPrice.pollFirst();
                        orderById.remove(resting.id);
                    }
                }

                if (ordersAtPrice.isEmpty()) {
                    bids.remove(bestBidPrice);
                }
            }
        }

        // Rest remaining quantity
        if (!incoming.isEmpty()) {
            TreeMap<Integer, LinkedList<Order>> book = incoming.isBuy ? bids : asks;
            if (!book.containsKey(incoming.price)) {
                book.put(incoming.price, new LinkedList<>());
            }
            book.get(incoming.price).addLast(incoming);
            orderById.put(incoming.id, incoming);
        }
    }

    static void cancelOrder(int id) {
        Order order = orderById.get(id);
        if (order == null) return;

        TreeMap<Integer, LinkedList<Order>> book = order.isBuy ? bids : asks;
        LinkedList<Order> ordersAtPrice = book.get(order.price);

        if (ordersAtPrice != null) {
            ordersAtPrice.remove(order);
            if (ordersAtPrice.isEmpty()) {
                book.remove(order.price);
            }
        }

        orderById.remove(id);
    }
}

